    public OrganizationService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new OrganizationEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(OrganizationRepository.class) );
		this.validator		= applicationContext.getBean(OrganizationValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Organization
	 */
		public Organization createOrganization( CreateOrganizationCommand command ) {

		Organization entity = new Organization();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setOrganizationId( command.getOrganizationId() );
            entity.setName( command.getName() );
            entity.setLegalName( command.getLegalName() );
            entity.setJurisdiction( command.getJurisdiction() );
            entity.setIndustrySector( command.getIndustrySector() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Organization {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateOrganizationCommand
	 * @return		Organization
	 */
	public Organization updateOrganization( UpdateOrganizationCommand command ) {

		Organization entity = new Organization();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setOrganizationId( command.getOrganizationId() );
            entity.setName( command.getName() );
            entity.setLegalName( command.getLegalName() );
            entity.setJurisdiction( command.getJurisdiction() );
            entity.setIndustrySector( command.getIndustrySector() );
            entity.setGovernanceBodies( command.getGovernanceBodies() );
            entity.setPolicies( command.getPolicies() );
            entity.setRisks( command.getRisks() );
            entity.setThirdParties( command.getThirdParties() );
            entity.setRecordsRepositories( command.getRecordsRepositories() );
            entity.setDataProcessingActivities( command.getDataProcessingActivities() );
            entity.setCompliancePrograms( command.getCompliancePrograms() );
            entity.setAuditPrograms( command.getAuditPrograms() );
            entity.setBusinessUnits( command.getBusinessUnits() );
            entity.setMatters( command.getMatters() );
            entity.setDataBreaches( command.getDataBreaches() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Organization {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteOrganizationCommand
	 */
	public void delete( DeleteOrganizationCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getOrganizationId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Organization {0} ", id );

	}

	/**
	 * Method to retrieve the Organization via OrganizationFetchOneSummary
	 * @param 	summary OrganizationFetchOneSummary
	 * @return 	OrganizationFetchOneResponse
	 */
	public Organization getOrganization( OrganizationFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "OrganizationFetchOneSummary arg cannot be null" );

		Organization entity = null;
		UUID id = summary.getOrganizationId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Organization using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Organizations
	 *
	 * @return 	List<Organization>
	 */
    public List<Organization> getAllOrganization() {
		List<Organization> list = projector.findAll( new FindAllOrganizationQuery() );
		return list;
	}


